import unittest
from candidate import unique

class TestUniqueFunction(unittest.TestCase):
    def test_unique_normal_case(self):
        self.assertEqual(unique([5, 3, 5, 2, 3, 3, 9, 0, 123]), [0, 2, 3, 5, 9, 123])

    def test_unique_empty_list(self):
        self.assertEqual(unique([]), [])

    def test_unique_single_element(self):
        self.assertEqual(unique([42]), [42])

    def test_unique_duplicate_first_last_elements(self):
        self.assertEqual(unique([1, 2, 2, 1, 3]), [1, 2, 3])

    def test_unique_all_duplicates(self):
        self.assertEqual(unique([7, 7, 7, 7]), [7])

    def test_unique_mixed_types(self):
        with self.assertRaises(TypeError):
            unique([1, 'a', 2])

    def test_unique_non_list_input(self):
        with self.assertRaises(TypeError):
            unique("not a list")

    def test_unique_nested_lists(self):
        with self.assertRaises(TypeError):
            unique([1, [2, 3]])

    def test_unique_with_negative_numbers(self):
        self.assertEqual(unique([-5, -3, -5, -2, -3, -3, -9, -0, 123]), [-9, -5, -3, -2, 0, 123])

    def test_unique_with_floats(self):
        self.assertEqual(unique([1.5, 2.5, 1.5, 3.5, 2.5, 2.5, 4.5]), [1.5, 2.5, 3.5, 4.5])

    def test_unique_with_mixed_floats_and_ints(self):
        self.assertEqual(unique([1, 2.5, 1, 3.0, 2.5, 2.5]), [1, 2.5, 3.0])

    def test_unique_with_large_numbers(self):
        self.assertEqual(unique([10**6, 10**6 - 1, 10**6, 10**6 + 1]), [10**6 - 1, 10**6, 10**6 + 1])

    def test_unique_with_duplicates_at_boundaries(self):
        self.assertEqual(unique([0, 0, 1, 1, 2, 2]), [0, 1, 2])

    def test_unique_with_duplicates_in_middle(self):
        self.assertEqual(unique([1, 2, 2, 2, 3, 4, 4, 4]), [1, 2, 3, 4])

    def test_unique_with_duplicates_in_reverse_order(self):
        self.assertEqual(unique([9, 5, 5, 3, 3, 2, 0]), [0, 2, 3, 5, 9])
